const ws = figma.root.children.find(p=>p.name.includes('03 · Workspace'));
const out = {pages: figma.root.children.map(p=>p.name+' | '+p.id)};
out.wsChildren = ws.children.map(n=>`${n.type}:${n.id}:${n.name}:${Math.round(n.width)}x${Math.round(n.height)}`);
const ids = ['5:123','5:112','5:4','5:33','5:17','5:10','1:28','1:33','1:44','5:126'];
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  if (!n) { out[id]='MISSING'; continue; }
  const info = {type:n.type, name:n.name, w:n.width, h:n.height};
  if (n.type==='COMPONENT'||n.type==='INSTANCE') {
    info.children = n.children.map(c=>`${c.type}:${c.name}:${Math.round(c.width)}x${Math.round(c.height)}`);
  }
  if ('fills' in n && n.fills && n.fills.length) info.fills = n.fills.map(f=>f.type+(f.imageHash?'#'+f.imageHash.slice(0,8):'')+(f.color?':'+JSON.stringify(f.color).slice(0,40):'')+(f.gradientStops?'grad':''));
  out[id]=info;
}
return JSON.stringify(out,null,1);

