for(const pg of [P]){ pg.findAllWithCriteria({types:['INSTANCE']}).forEach(n=>nodes.push(n)); }
for(const n of nodes){
  const compName = n.mainComponent ? n.mainComponent.name : '';
  if(compName.indexOf('Icon_')===0){
    n.fills=[]; n.strokes=[]; fixed++;
    // neutralize any stray background rectangles inside
    const walk=(x)=>{ if(x.type==='RECTANGLE' && x.width>=23 && x.height>=23 && x.fills && x.fills.some(f=>f.type==='SOLID')) { x.fills=[]; } if(x.children) x.children.forEach(walk); };
    walk(n);
  }
}
return 'cleaned '+fixed;

